package com.ayushig.localrag.testing

import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * A small real bundle (3 chunks of "brokerage-charges", contentVersion 47, BM25 only plus
 * 4-dimensional vectors) written by the JVM BundleWriter. Copied from localrag-core's golden
 * fixture so SDK tests can load a genuine bundle without file resources, on every platform.
 */
@OptIn(ExperimentalEncodingApi::class)
internal object SdkTestBundle {
    private const val BASE64 = ""

    fun bytes(): ByteArray = Base64.decode(BASE64)
}
